async chooseMusic(text, songs, counts = null) {
	const names = (Array.isArray(songs) ? songs : []).map((s) => String(s ?? '').trim()).filter(Boolean);
	const list = [...new Set(names)].slice(0, 10);
	if (!list.length) return { song: '', duplicate: false };
	// FS-MUSIC-TRACE：推荐歌里常混着「@某某创作的原声」「自带流量」这类不是歌的条目，先滤掉再交给模型挑；
	// 模型仍然挑不出来就照上游规矩不配乐（不发布），这里不硬塞兜底。
	const junk = /(创作的原声|自带流量|纯音乐|伴奏|BGM)/i;
	const usable = list.filter((s) => !junk.test(s));
	const cand = usable.length ? usable : list;
	try {
		const raw = String((await this.callLlm(`给这条抖音图文配背景音乐。从下面这些抖音推荐歌里挑一首最适合的（歌名原样照抄），不适合就回空串。\n\n图文正文：\n${text}\n\n推荐歌：\n${cand.map((s) => `- ${s}`).join('\n')}\n\n只输出歌名，不要别的。`)) ?? '').trim();
		const song = pickRecommendedSong(raw, cand) || pickRecommendedSong(raw, list);
		if (song !== '') this.note('post', { title: this.label, reason: `配了首《${song}》` });
		const n = counts && typeof counts === 'object' ? Number(counts[song]) || 0 : names.filter((s) => s === song).length;
		return { song, duplicate: song !== '' && n > 1 };
	} catch { throw new Error('配乐失败，未发布：模型选歌调用出错'); }
}

